import React, { useState, useEffect } from 'react';
import './Board.css';
import { getValueFromCoordinates, getCoordinatesFromValue } from './coordinates.js';

const Board = ({ gameData, socket }) => {
  const gridSize = 11; // Board size
  const centerIndex = Math.floor(gridSize / 2); // Center index for cross shape

  const { pieces: initialPieces } = gameData.board;
  const { players } = gameData;

  const [pieces, setPieces] = useState(initialPieces); // Store positions of the pieces
  const [loading, setLoading] = useState(false); // Flag to track if a move is in progress
  const [selectedPiece, setSelectedPiece] = useState(null); // To store the selected piece for movement
  const [error, setError] = useState(null); // Store error messages
  const [statusMessage, setStatusMessage] = useState(""); // Store status message
  const [diceRoll, setDiceRoll] = useState(null); // Store the dice roll result

  useEffect(() => {
    if (!socket) return;

    // Event listeners for socket connection and disconnection
    socket.on('connect', () => {
      console.log('Socket connected: ', socket.id);
    });

    socket.on('disconnect', () => {
      console.log('Disconnected from server.');
    });

    // Handle game updates
    socket.on('game:updated', (data) => {
      const { updatedPiece, nextPlayerId } = data;

      if (updatedPiece) {
        const { ownerId, color, commonPosition } = updatedPiece;
        console.log(`Player ${ownerId} moved ${color} piece to position ${commonPosition}`);

        // Update the piece position in the state
        setPieces(prevPieces =>
          prevPieces.map(piece =>
            piece.ownerId === ownerId && piece.color === color
              ? { ...piece, position: commonPosition }
              : piece
          )
        );

        if (nextPlayerId) {
          setStatusMessage(`It's player ${nextPlayerId}'s turn.`);
        }
      }
    });

    // Handle dice rolls
    socket.on('game:diceRolled', (data) => {
      const { playerId, dice, canDeploy } = data;
      setDiceRoll(dice);
      setStatusMessage(`Player ${playerId} rolled a ${dice}.`);

      if (canDeploy) {
        setStatusMessage(`Player ${playerId} can deploy a new piece!`);
      }
    });

    // Cleanup event listeners when the component is unmounted
    return () => {
      socket.off('game:updated');
      socket.off('game:diceRolled');
    };
  }, [socket]);

  // Function to check if a tile is part of the cross shape
  const isCrossTile = (row, col) => {
    if (row === centerIndex && col === centerIndex) {
      return false;
    }

    return (
      (col >= centerIndex - 1 && col <= centerIndex + 1) ||
      (row >= centerIndex - 1 && row <= centerIndex + 1) ||
      (row <= 1 && col <= 1) ||
      (row >= 9 && col >= 9) ||
      (row <= 1 && col >= 9) ||
      (row >= 9 && col <= 1)
    );
  };

  // Function to determine the tile color based on the player's position
  const getTileColor = (row, col) => {
    if (!isCrossTile(row, col)) return 'white';
    let color = 'white';

    players.forEach(player => {
      if (player.color === 'red' && ((row === 4 && col === 0) || (row === 5 && col >= 1 && col <= 4) || (row >= 0 && row <= 1 && col >= 0 && col <= 1))) {
        color = 'red';
      } else if (player.color === 'yellow' && ((row === 0 && col === 6) || (row >= 1 && row <= 4 && col === 5) || (row <= 1 && col >= 9))) {
        color = 'yellow';
      } else if (player.color === 'green' && ((row === 6 && col === 10) || (row === 5 && col >= 6 && col <= 9) || (row >= 9 && row <= 10 && col >= 9 && col <= 10))) {
        color = 'green';
      } else if (player.color === 'blue' && ((row === 10 && col === 4) || (row >= 6 && row <= 9 && col === 5) || (row >= 9 && col <= 1))) {
        color = 'blue';
      }
    });

    return color;
  };

  // Function to render the piece at a given row and col
  const renderPiece = (row, col) => {
    const piece = pieces.find(p => {
      const { row: pieceRow, col: pieceCol } = getCoordinatesFromValue(p.position, p.color);
      return pieceRow === row && pieceCol === col;
    });

    if (piece) {
      return (
        <div className="piece" style={{ backgroundColor: piece.color, width: '70%', height: '70%' }}></div>
      );
    }
    return null;
  };

  // Emit a "game:play" event for dice roll
  const emitGamePlayEvent = () => {
    if (socket) {
      console.log('Emitting game:play event');
      socket.emit('game:play');
    }
  };

  // Handle tile click, perform a move if possible
  const handleTileClick = (row, col) => {
    if (loading) {
      setError("Please wait until the current turn is completed.");
      return;
    }

    // If a piece is already selected, move it to the clicked tile
    if (selectedPiece) {
      const validMove = checkMoveValidity(selectedPiece, row, col);

      if (validMove) {
        // Update the piece position
        const commonPosition = getValueFromCoordinates(row, col, selectedPiece.color)

        // Send the move to the server
        socket.emit('game:movePiece', { commonPosition }, (data) => {
          console.log('Received response from server:', data);
        });

        setSelectedPiece(null); // Deselect the piece after move
        setLoading(true);
        setError(null);
      } else {
        setError("Invalid move. Select a valid tile.");
      }
    } else {
      // If no piece is selected, select a piece on the clicked tile
      const clickedPiece = pieces.find(p => getValueFromCoordinates(row, col, p.color) === p.position);

      if (clickedPiece) {
        setSelectedPiece(clickedPiece);
        setStatusMessage(`Selected ${clickedPiece.color} piece.`);
      } else {
        setError("No piece on this tile.");
      }
    }
  };

  // Function to check if the move is valid
  const checkMoveValidity = (piece, row, col) => {
    // Add the logic to check if the move is valid based on the dice roll or other rules
    // Example: Just checking if the destination is not the same as the current position
    const currentPosition = getCoordinatesFromValue(piece.position, piece.color);
    return currentPosition.row !== row || currentPosition.col !== col;
  };

  return (
    <div>
      {/* Dice roll button outside the board */}
      <div style={{ marginBottom: '20px', display: 'flex', justifyContent: 'center' }}>
        <button 
          onClick={emitGamePlayEvent}
          style={{
            padding: '10px 20px', 
            fontSize: '16px', 
            cursor: 'pointer', 
            backgroundColor: '#4CAF50', 
            color: 'white', 
            border: 'none', 
            borderRadius: '5px'
          }}
        >
          Roll Dice
        </button>
      </div>

      {/* Displaying status messages and dice roll */}
      {statusMessage && <div className="status-message">{statusMessage}</div>}
      {error && <div className="error">{error}</div>}
      {diceRoll !== null && <div className="dice-roll">Dice Roll: {diceRoll}</div>}

      {/* Board rendering */}
      <div className="board">
        {Array.from({ length: gridSize * gridSize }).map((_, index) => {
          const row = Math.floor(index / gridSize);
          const col = index % gridSize;
          const tileColor = getTileColor(row, col);

          return (
            <div
              className={`tile ${isCrossTile(row, col) ? '' : 'empty-tile'}`}
              style={{
                backgroundColor: tileColor,
                width: '40px',
                height: '40px',
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                border: '1px solid #ccc',
                cursor: 'pointer',
              }}
              key={index}
              onClick={() => handleTileClick(row, col)}
            >
              {renderPiece(row, col)}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Board;
